SELECT 
FROM schedule
WHERE department_id = #{departmentId}
  AND schedule_date BETWEEN #{startDate} AND #{endDate}
  AND status = 1
ORDER BY schedule_date ASC, period ASC

SELECT 
FROM schedule
WHERE doctor_id = #{doctorId}
  AND schedule_date = #{scheduleDate}
  AND period = #{period}

SELECT FROM schedule WHERE id IN
#{item}
ORDER BY id ASC
